INSERT INTO emp VALUES (1, 1), (2, 1), (3, 2);
SELECT d.name, COUNT(e.id)
FROM dept d LEFT JOIN emp e ON e.dept_id = d.id
GROUP BY d.name ORDER BY d.name;
```

